def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

python
def factorial_recursive(n):
    """
    गैर-ऋणात्मक पूर्णांक 'n' का फ़ैक्टोरियल, पुनरावर्तन का उपयोग करके गणना करता है।
    0 का फ़ैक्टोरियल 1 परिभाषित है।

    त्रुटि:
        ValueError: यदि n ऋणात्मक है।
    """
    if n < 0:
        raise ValueError("ऋणात्मक संख्याओं के लिए फ़ैक्टोरियल परिभाषित नहीं है।")
    elif n == 0:
        return 1
    else:
        return n * factorial_recursive(n - 1)

# उदाहरण उपयोग:
# print(factorial_recursive(5)) # आउटपुट: 120

