def fibonacci_recursive(n):
    """nth फ़ाइबोनैची संख्या की गणना पुनरावर्ती तरीके से करता है।
    गैर-धनात्मक निवेश (inputs) के लिए 0 लौटाता है।
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

# प्रिंट(fibonacci_recursive(8)) # परिणाम: 21

